def romano_a_entero(s):
    valores = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, c in enumerate(s):
        v = valores[c]
        if i + 1 < len(s) and valores[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total
