def entero_a_romano(n):
    if not 1 <= n <= 3999:
        raise ValueError("fuera de rango")
    tabla = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    salida = []
    for valor, simbolo in tabla:
        while n >= valor:
            salida.append(simbolo)
            n -= valor
    return "".join(salida)
```

