def cesar(texto, desplazamiento):
    salida = []
    for c in texto:
        if "a" <= c <= "z":
            salida.append(chr((ord(c) - 97 + desplazamiento) % 26 + 97))
        elif "A" <= c <= "Z":
            salida.append(chr((ord(c) - 65 + desplazamiento) % 26 + 65))
        else:
            salida.append(c)
    return "".join(salida)
```

