def buscar(lista_ordenada, x):
    lo, hi = 0, len(lista_ordenada) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if lista_ordenada[mid] == x:
            return mid
        if lista_ordenada[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
```

